with filtered as (select id, full_name, email, dept_id, manager_id, salary, hire_date, level, lower(job_title) as job_title_lower, concat_ws(',', job_title, email) as job_title_email_key from employees where hire_date >= to_date('2023-09-25') and hire_date between '2023-11-01' and '2025-04-01'), metrics as (select *, avg(salary) over (partition by dept_id order by salary asc, id asc rows between 5 preceding and 1 preceding) as salary_avg_5_prior, first_value(level) ignore nulls over (partition by dept_id, manager_id order by salary asc, id asc rows between unbounded preceding and current row) as first_known_level, row_number() over (partition by level order by hire_date asc, id asc) as event_seq, min(salary) over (partition by dept_id) as dept_id_min_salary from filtered), deduped as (select * from metrics qualify row_number() over (partition by dept_id order by event_seq asc, id asc) = 1), pivoted as (select * from (select manager_id, level, salary_avg_5_prior from deduped) src pivot (sum(salary_avg_5_prior) for level in ('L2', 'L1', 'L4'))) select manager_id, L2 from pivoted order by L2 desc nulls first, manager_id asc limit 5;
